#!/usr/bin/env node
import { readdir, readFile, writeFile } from 'node:fs/promises'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const contentRoot = join(root, 'modules/nuc_documentation/content')
const outFile = join(
  root,
  'modules/nuc_documentation/utils/markdown_bundle.generated.ts'
)

async function collectMarkdownFiles(dir) {
  const entries = await readdir(dir, { withFileTypes: true })
  const files = []

  for (const entry of entries) {
    const fullPath = join(dir, entry.name)
    if (entry.isDirectory()) {
      files.push(...(await collectMarkdownFiles(fullPath)))
      continue
    }
    if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(fullPath)
    }
  }

  return files
}

const files = (await collectMarkdownFiles(contentRoot)).sort()
const lines = [
  '// AUTO-GENERATED by scripts/generate-doc-markdown-bundle.mjs — do not edit.',
  'export const MARKDOWN_BUNDLE: Record<string, string> = {',
]

for (const file of files) {
  const rel = relative(contentRoot, file).replaceAll('\\', '/')
  const key = rel.replace(/\.md$/, '')
  const text = await readFile(file, 'utf-8')
  lines.push(`  ${JSON.stringify(key)}: ${JSON.stringify(text)},`)
}

lines.push('}')
lines.push('')
lines.push(
  'export function getBundledMarkdown(lang: string, category: string, slug: string): string | null {'
)
lines.push('  return MARKDOWN_BUNDLE[`${lang}/${category}/${slug}`] ?? null')
lines.push('}')
lines.push('')

await writeFile(outFile, lines.join('\n'), 'utf-8')
console.log(`Generated ${files.length} docs -> ${outFile}`)
